/**
 * 主要地域（首都圏・関西・愛知・福岡）の学校を、偏差値目安・部活付きで拡充したデータ。
 * 部活は公式サイト等で存在を確認できたものだけを載せる（無いものは「未確認」扱い）。
 * 偏差値は複数の受験情報サイトで公表されている目安を丸めた値。年度で変わるため必ず最新の資料で確認。
 */
type Quick = {
  id: string
  name: string
  pref: string
  city: string
  kind: SchoolKind
  h: number
  gender?: Gender
  course?: string
  /** 最寄り駅と徒歩・バス分 */
  st?: [string, number]
  /** 県庁所在地付近からの通学目安（分） */
  cm?: number
  clubs: string[]
  feat: string[]
  atm: string[]
  tags: Priority[]
  uni: string
  desc: string
  lifestyle?: Seed['lifestyle']
  tuition?: Seed['tuition']
}

