function notes(q: Quick) {
  const top = q.h >= 67
  const mid = q.h >= 57 && q.h < 67
  const teacher = top
    ? '授業の予習復習が習慣になっている子と相性がよい学校です。入ってからの伸びは、入試の点より学習習慣で決まります。'
    : mid
      ? '基礎が固まっていれば十分に狙える帯です。提出物・授業態度など内申の安定が合否と入学後の両方に効きます。'
      : '「行けるから」ではなく「通いたいか」で選ぶと3年間が変わります。見学で先生と生徒の距離感を確かめてください。'
  const juku = top
    ? '本命にするなら夏までに中1・中2の穴を埋め、秋から過去問。併願の安全校を先に固めて。'
    : mid
      ? '模試偏差値だけで決めず、内申の比重と入試方式を確認。得意科目で稼げる配点かを見て。'
      : q.kind === '私立'
        ? '併願優遇・推薦の基準（内申○以上など）を早めに確認。単願なら基準を満たせるかを数字で。'
        : '安全校として見るなら、進路実績（大学・専門・就職）を必ず確認。部活の活動日数も比べて。'
  const student = q.kind === '私立'
    ? '施設や行事が充実している分、学費と校則を家族で確認しておくと安心です。'
    : q.h >= 62
      ? '行事も部活も生徒が仕切る場面が多く、忙しいけれど密度の高い3年間です。'
      : '通学のしやすさと部活の雰囲気で決めた人が多いです。見学の日に部活を見せてもらって。'
  return { teacherNote: teacher, jukuNote: juku, studentNote: student }
}

function q(x: Quick): Seed {
  const ex = EXAM[`${x.pref}|${x.kind}`] ?? { style: '学力検査＋調査書', season: '2〜3月', key: `${x.kind === '私立' ? 'private' : 'public'}-generic` }
  return {
    id: x.id,
    name: x.name,
    prefecture: x.pref,
    city: x.city,
    kind: x.kind,
    gender: x.gender,
    course: x.course ?? '普通科',
    hensachi: x.h,
    commuteMin: x.cm ?? 35,
    station: x.st?.[0],
    stationMin: x.st?.[1],
    tuition: x.tuition,
    clubs: x.clubs,
    features: x.feat,
    atmosphere: x.atm,
    tags: x.tags,
    university: x.uni,
    examStyle: ex.style,
    examSeason: ex.season,
    dateKey: ex.key,
    lifestyle: x.lifestyle,
    description: x.desc,
    ...notes(x),
  }
}

